  "type": "object",
  "properties": {
    "studentId": { "type": "string", "format": "uuid" },
    "indicatorType": {
      "type": "string",
      "enum": ["social_isolation", "attendance_drop", "counseling_visits", "conduct_association", "irregular_sleep"]
    },
    "value": { "type": "number", "description": "Raw metric (e.g., hours alone, visit count)" },
    "thresholdBreached": { "type": "boolean" },
    "analysisWindow": { "type": "string", "format": "date-time", "description": "Start of window" }
  },
