    "deviceId": { "type": "string", "description": "Badge serial (e.g., 'BADGE-001')" },
    "timestamp": { "type": "string", "format": "date-time" },
    "location": {
      "type": "object",
      "properties": {
        "zone": { "type": "string", "enum": ["ZoneA", "ZoneB", "ZoneC", "..."] },
        "coordinates": { "type": "array", "items": { "type": "number" }, "minItems": 3, "maxItems": 3 }  // [x, y, z] via UWB
      },
      "required": ["zone", "coordinates"]
    },
    "proximity": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "entity": { "type": "string", "enum": ["HeavyEquipment", "HazmatZone"] },
          "distance": { "type": "number", "description": "Meters" },
          "alert": { "type": "boolean", "description": "True if within threshold (e.g., <5m)" }
        }
      }
    },
    "biometrics": {
      "type": "object",
      "properties": {
        "heartRate": { "type": "number", "description": "Beats per minute (bpm)" },
        "skinTemperature": { "type": "number", "description": "Degrees Celsius" }
      }
    },
    "noiseExposure": {
      "type": "object",
      "properties": {
        "instantaneous": { "type": "number", "description": "Current dBA" },
        "cumulative": { "type": "number", "description": "Time-weighted average (TWA) against OSHA PEL" }
      }
    },
    "movement": {
      "type": "object",
      "properties": {
        "variability": { "type": "number", "description": "Standard deviation of speed over 5-min window (m/s)" }
      }
    }
  },
  "required": ["workerId", "deviceId", "timestamp", "location"]
}
```

### 1.2 Fatigue Detection Output Schema
Generated by the algorithm; includes fatigue indicators and thresholds.

```json
