      "properties": {
        "metrics": {
          "type": "object",
          "properties": {
            "appointmentAttendance": {
              "type": "object",
              "properties": {
                "totalScheduled": { "type": "integer", "minimum": 0 },
                "attended": { "type": "integer", "minimum": 0 },
                "adherenceRate": { "type": "number", "description": "Calculated as (attended / totalScheduled) * 100", "minimum": 0, "maximum": 100 }
              }
            },
            "referralFollowThrough": {
              "type": "object",
              "properties": {
                "totalReferrals": { "type": "integer", "minimum": 0 },
                "completed": { "type": "integer", "minimum": 0 },
                "adherenceRate": { "type": "number", "description": "Calculated as (completed / totalReferrals) * 100", "minimum": 0, "maximum": 100 }
              }
            },
            "documentSubmission": {
              "type": "object",
              "properties": {
                "totalRequired": { "type": "integer", "minimum": 0 },
                "submitted": { "type": "integer", "minimum": 0 },
                "adherenceRate": { "type": "number", "description": "Calculated as (submitted / totalRequired) * 100", "minimum": 0, "maximum": 100 }
              }
            }
